#!/usr/bin/env python3
"""Writes THIRD-PARTY-LICENSES.md: the licence texts of the crates linked into wirust.

    python3 .github/scripts/third-party-licenses.py > THIRD-PARTY-LICENSES.md
    python3 .github/scripts/third-party-licenses.py --check    # fails when the file is stale

The MIT, BSD, ISC and Apache-2.0 licences ask that a binary distribution reproduce the
copyright notice and the licence text. This lists, for the `wirust` binary, every crate
that `cargo tree` shows as a normal (not dev, not build, not proc-macro) dependency of the
`wirust` package for any of the release targets in .github/workflows/release.yml, with its licence expression and the
licence files that ship in the crate. Crates whose files are byte for byte the same are
printed once. Packages that `cargo tree` prints with a path or URL in parentheses (the
workspace and the `fingerprint` git dependency, both GPL-3.0-only) are left out; their
registry dependencies are not. The output depends only on Cargo.lock and the downloaded crate sources, so
the same lock file gives the same text. Run it from the repository root after a change to
Cargo.lock and commit the result. It needs only Python 3.9 and cargo.
"""

import hashlib
import json
import os
import re
import subprocess
import sys

# Keep in step with the matrix of .github/workflows/release.yml.
TARGETS = [
    "x86_64-unknown-linux-musl",
    "aarch64-unknown-linux-musl",
    "aarch64-apple-darwin",
    "x86_64-apple-darwin",
    "x86_64-pc-windows-msvc",
]
ROOT_PACKAGE = "wirust"
OUTPUT = "THIRD-PARTY-LICENSES.md"
LICENSE_FILE = re.compile(r"^(licen[cs]e|copying|unlicense|notice)([-_.].*)?$", re.IGNORECASE)


def run(*args):
    return subprocess.run(args, check=True, capture_output=True, text=True).stdout


def linked_crates(target):
    """(name, version) of every registry crate linked into the binary for the target.

    Reads `cargo tree`, which resolves features and platform-specific dependencies;
    `cargo metadata` lists optional dependencies that no feature turns on.
    """
    tree = run(
        "cargo", "tree", "--locked", "--package", ROOT_PACKAGE, "--edges", "normal",
        "--target", target, "--no-dedupe", "--prefix", "depth", "--format", "{p}",
    )
    crates = set()
    skip_below = None
    for line in tree.splitlines():
        depth, text = re.match(r"(\d+)(.*)", line).groups()
        depth = int(depth)
        if skip_below is not None and depth > skip_below:
            continue
        skip_below = None
        # Procedural macros run at compile time: neither they nor what only they use
        # (syn, quote, proc-macro2) is part of the binary.
        if text.endswith("(proc-macro)"):
            skip_below = depth
            continue
        name, version, *path = text.split(" ", 2)
        if not path:  # a path in parentheses marks a workspace package
            crates.add((name, version.removeprefix("v")))
    return crates


def license_files(package):
    root = os.path.dirname(package["manifest_path"])
    files = []
    for name in sorted(os.listdir(root)):
        path = os.path.join(root, name)
        if os.path.isfile(path) and LICENSE_FILE.match(name):
            with open(path, "rb") as f:
                files.append((name, f.read().decode("utf-8", errors="replace").strip("\n")))
    return files


def main():
    meta = json.loads(run("cargo", "metadata", "--format-version", "1", "--locked"))
    known = {(p["name"], p["version"]): p for p in meta["packages"]}
    wanted = set().union(*(linked_crates(target) for target in TARGETS))
    packages = {key: known[key] for key in wanted}

    groups = {}
    for key in sorted(packages):
        package = packages[key]
        files = license_files(package)
        digest = hashlib.sha256(
            json.dumps([package["license"], files], sort_keys=True).encode()
        ).hexdigest()
        groups.setdefault(digest, {"license": package["license"], "files": files, "crates": []})
        groups[digest]["crates"].append(f"{package['name']} {package['version']}")

    lines = [
        "# Third-party licenses",
        "",
        "wirust itself is licensed under GPL-3.0-only (see `LICENSE` and `NOTICE`). The binary",
        f"links the {len(packages)} Rust crates below, each under its own licence. The texts are",
        "those shipped in the crates' sources; crates with identical texts are listed together.",
        "This file is generated by `.github/scripts/third-party-licenses.py` from `Cargo.lock`.",
        "The `fingerprint` crate of mirrust, a git dependency under GPL-3.0-only like wirust,",
        "is not listed here; see `NOTICE`.",
        "",
    ]
    for group in sorted(groups.values(), key=lambda g: g["crates"][0].lower()):
        lines.append(f"## {', '.join(group['crates'])}")
        lines.append("")
        lines.append(f"Licence: {group['license'] or 'not stated in Cargo.toml'}")
        lines.append("")
        if not group["files"]:
            lines.append("The crate ships no licence file; the licence is the one stated above.")
            lines.append("")
        for name, text in group["files"]:
            lines.append(f"### {name}")
            lines.append("")
            lines.append("``````text")
            lines.append(text)
            lines.append("``````")
            lines.append("")
    text = "\n".join(lines)

    if "--check" in sys.argv[1:]:
        with open(OUTPUT, encoding="utf-8") as f:
            if f.read() != text:
                print(f"{OUTPUT} is stale: run this script and commit the result", file=sys.stderr)
                return 1
        print(f"{OUTPUT} is up to date ({len(packages)} crates)")
        return 0
    sys.stdout.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())
